using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.ENC.OpcionesPregunta;using GraphApi.Services.ENC.OpcionesPregunta;namespace GraphApi.Controllers.ENC.OpcionesPregunta{    /// <summary>    /// Gestión de OpcionesPreguntas: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("ENC/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre OpcionesPreguntas")]    public class OpcionesPreguntaController : Controller    {        private readonly IOpcionesPreguntaService _objService;        public OpcionesPreguntaController(IOpcionesPreguntaService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los OpcionesPreguntas, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="opcionPreguntaID">OpcionPreguntaID</param>        /// <param name="preguntaID">PreguntaID</param>        /// <param name="texto">Texto</param>        /// <param name="valor">Valor</param>        /// <param name="orden">Orden</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de OpcionesPreguntas</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar OpcionesPreguntas",            Description = "Devuelve OpcionesPreguntas aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadOpcionesPregunta>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadOpcionesPregunta>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? opcionPreguntaID,            [FromQuery] int? preguntaID,            [FromQuery] string? texto,            [FromQuery] string? valor,            [FromQuery] int? orden,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetOpcionesPreguntasDynamic(                opcionPreguntaID,                 preguntaID,                 texto,                 valor,                 orden,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo OpcionesPregunta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del OpcionesPregunta a crear.</param>        /// <returns>El OpcionesPregunta recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear OpcionesPreguntas",            Description = "Inserta un nuevo OpcionesPregunta en la base de datos."        )]        [ProducesResponseType(typeof(clReadOpcionesPregunta), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadOpcionesPregunta>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateOpcionesPregunta objInput)        {            var vCreated = await _objService.CreateOpcionesPregunta(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de OpcionesPregunta.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del OpcionesPregunta.</param>        /// <returns>El OpcionesPregunta actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar OpcionesPreguntas",            Description = "Actualiza uno o varios campos de OpcionesPregunta existente."        )]        [ProducesResponseType(typeof(clReadOpcionesPregunta), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadOpcionesPregunta>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateOpcionesPregunta objInput)        {            var vUpdated = await _objService.UpdateOpcionesPregunta(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un OpcionesPregunta por su ID.        /// </summary>        [HttpDelete("{nOpcionesPreguntaID:int}")]        [SwaggerOperation(            Summary = "Eliminar OpcionesPregunta",            Description = "Borra un OpcionesPregunta si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nOpcionesPreguntaID)        {            var success = await _objService.DeleteOpcionesPregunta(nOpcionesPreguntaID);            return success ? NoContent() : NotFound();        }    }}